(1, 'Testando Imbecil', 'Mensagem de teste exemplo Caixa D\'Agua:\r\nSua Caixa d\'agua vence em 30 dias', '2021-05-04 17:56:10', 0, 1, NULL, '2021-05-04 17:56:10'),
(2, 'Testando Imbecil', 'Mensagem de teste exemplo Caixa D\'Agua: Sua Caixa d\'agua vence em 30 dias', '2021-05-04 17:57:55', 0, 1, NULL, '2021-05-04 17:57:55'),
(3, 'coleta de óleo.', 'caros colegas! você já possui o programa de coleta de óleo em seu condomínio? se não peça pelo nosso APP, e mostre aos seus condomínios que você se preocupa com meio ambiente e gerencia com competência o condomínio.', '2021-05-16 00:33:31', 0, 1, NULL, '2021-05-16 00:33:31'),
(4, 'teste de envio', 'bom dia este é apenas um teste para verificar o funcionamento da ferramenta.', '2021-05-18 11:50:28', 0, 1, NULL, '2021-05-18 11:50:28'),
(5, 'teste', 'CASA DO SINDICO a melhor ferramenta de trabalho para os síndicos do BRASIL.', '2021-05-18 12:02:38', 0, 1, NULL, '2021-05-18 12:02:38'),
(6, 'teste', 'CASA DO SINDICO a melhor ferramenta de trabalho para os síndicos do BRASIL.', '2021-05-18 12:02:48', 0, 1, NULL, '2021-05-18 12:02:48'),
(7, 'benvinda!!', 'seja bem vinda a melhor ferramenta de trabalho para os síndicos do Brasil.', '2021-05-22 15:33:38', 0, 1, NULL, '2021-05-22 15:33:38');
