(1286, '2018-02-22 17:22:01', 50, 'Mirante Sul', 'Andre', 'sindicomirantesul2018@gmail.com', '48991804535', 'Rua Hipólito Mafra', '203', '', 'Saco dos Limões', 8213, 24, '88045410', 'Antena Digital', 'Bom dia,\r\nGostaria de fazer um orçamento p/ antena digital.\r\nO residencial com 3 blocos e 100 apartamentos.\r\nAtt, André', '201.86.66.37', 'UALACE DEIVIS DOS SANTOS FERNANDES', 'NIÓBIO', 'niobioprodutora@gmail.com', 1, NULL, NULL, NULL),
(1287, '2018-02-22 17:26:36', 58, 'Mirante Sul', 'Andre', 'sindicomirantesul2018@gmail.com', '48991804535', 'Rua Hipólito Mafra', '203', '', 'Saco dos Limões', 8213, 24, '88045410', 'Portaria remota', 'Bom dia,\r\nHoje temos a portaria 24h com uma empresa terceirizada, mas gostaria de fazer um orçamento para transformar a nossa portaria em remota, virtual.\r\nAcredito que a melhor alternativa é conversarmos a respeito no próprio condomínio.\r\nFico no aguardo.\r\nAtt, André\r\n', '201.86.66.37', 'Renato Pfeiffer Porto', 'ATTENTO PORTARIA INTELIGENTE', 'renato.porto@attento.com.br', 1, NULL, NULL, NULL),
